// worker-service/src/handler.rs
// Step Functions task worker that processes memory buffers from upstream services
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use hyper::{Body, Request, Response, Server, StatusCode};
use hyper::service::{make_service_fn, service_fn};
use serde::{Deserialize, Serialize};
use tokio::sync::oneshot;

#[derive(Deserialize)]
struct TaskInput {
    execution_id: String,
    buffer_ref: String,
    action: String,
    source_namespace: Option<String>,
}

#[derive(Serialize)]
struct TaskOutput {
    status: String,
    execution_id: String,
}

struct BufferPool {
    buffers: HashMap<String, *mut u8>,
    freed: HashMap<String, bool>,
}

unsafe impl Send for BufferPool {}
unsafe impl Sync for BufferPool {}

impl BufferPool {
    fn new() -> Self {
        BufferPool {
            buffers: HashMap::new(),
            freed: HashMap::new(),
        }
    }

    fn allocate(&mut self, key: &str, size: usize) -> *mut u8 {
        let layout = std::alloc::Layout::from_size_align(size, 8).unwrap();
        let ptr = unsafe { std::alloc::alloc(layout) };
        self.buffers.insert(key.to_string(), ptr);
        self.freed.insert(key.to_string(), false);
        ptr
    }

    // BUG: No guard against double-free when concurrent Step Functions
    // retries invoke both "process" and "cleanup" actions on same buffer_ref
    fn release(&mut self, key: &str) -> Result<(), String> {
        if let Some(ptr) = self.buffers.get(key) {
            let layout = std::alloc::Layout::from_size_align(4096, 8).unwrap();
            unsafe { std::alloc::dealloc(*ptr, layout); }
            // NOTE: we mark freed but do NOT remove from buffers map
            // A second call with same key will dealloc the same pointer
            self.freed.insert(key.to_string(), true);
            Ok(())
        } else {
            Err("buffer not found".to_string())
        }
    }
}

static POOL: once_cell::sync::Lazy<Arc<Mutex<BufferPool>>> =
    once_cell::sync::Lazy::new(|| Arc::new(Mutex::new(BufferPool::new())));

async fn handle_task(req: Request<Body>) -> Result<Response<Body>, hyper::Error> {
    let body = hyper::body::to_bytes(req.body_mut().await.unwrap()).await.unwrap();
    let input: TaskInput = match serde_json::from_slice(&body) {
        Ok(v) => v,
        Err(_) => return Ok(Response::builder()
            .status(StatusCode::BAD_REQUEST)
            .body(Body::from("invalid json")).unwrap()),
    };

    let mut pool = POOL.lock().unwrap();

    match input.action.as_str() {
        "allocate" => {
            pool.allocate(&input.buffer_ref, 4096);
            let out = TaskOutput { status: "allocated".into(), execution_id: input.execution_id };
            Ok(Response::new(Body::from(serde_json::to_string(&out).unwrap())))
        }
        "process" => {
            // Process then release
            let _ = pool.release(&input.buffer_ref);
            let out = TaskOutput { status: "processed".into(), execution_id: input.execution_id };
            Ok(Response::new(Body::from(serde_json::to_string(&out).unwrap())))
        }
        "cleanup" => {
            // Cleanup also releases - double free if process already ran
            let _ = pool.release(&input.buffer_ref);
            let out = TaskOutput { status: "cleaned".into(), execution_id: input.execution_id };
            Ok(Response::new(Body::from(serde_json::to_string(&out).unwrap())))
        }
        _ => Ok(Response::builder()
            .status(StatusCode::BAD_REQUEST)
            .body(Body::from("unknown action")).unwrap()),
    }
}

#[tokio::main]
async fn main() {
    let addr = ([0, 0, 0, 0], 8080).into();
    let svc = make_service_fn(|_| async { Ok::<_, hyper::Error>(service_fn(handle_task)) });
    Server::bind(&addr).serve(svc).await.unwrap();
}
